USE nyc_taxi_ldw;
DECLARE @sql NVARCHAR(MAX);

SELECT @sql = STRING_AGG(
        CAST('EXEC silver.usp_silver_trip_data_green ''' 
        + CAST(year AS VARCHAR(4)) + ''','''
        + RIGHT('0' + CAST(month AS VARCHAR(2)), 2) + ''';' AS NVARCHAR(MAX)),
        CHAR(10)
    )
FROM (
        SELECT DISTINCT
               CAST(year AS VARCHAR(4)) AS year,
               RIGHT('0' + CAST(month AS VARCHAR(2)), 2) AS month
        FROM bronze.vw_trip_data_green_csv
     ) AS x;

PRINT(@sql);
EXEC(@sql);

USE nyc_taxi_ldw;
GO

CREATE OR ALTER PROCEDURE silver.usp_silver_trip_data_green
    @year  VARCHAR(4),
    @month VARCHAR(2)
AS
BEGIN

    DECLARE @create_sql_stmt NVARCHAR(MAX),
            @drop_sql_stmt   NVARCHAR(MAX),
            @table_name      NVARCHAR(200);

    SET @table_name = 'trip_data_green_' + @year + '_' + @month;

    -- Create external table dynamically
    SET @create_sql_stmt = '
        CREATE EXTERNAL TABLE silver.' + @table_name + '
        WITH
        (
            LOCATION = ''silver/trip_data_green/year=' + @year + '/month=' + @month + ''',
            DATA_SOURCE = nyc_taxi_src,
            FILE_FORMAT = parquet_file_format
        )
        AS
        SELECT *
        FROM bronze.vw_trip_data_green_csv
        WHERE year = ''' + @year + '''
        AND month = ''' + @month + ''';';

    EXEC sp_executesql @create_sql_stmt;

    -- Drop external table if exists
    SET @drop_sql_stmt =
        'IF EXISTS (SELECT * FROM sys.external_tables WHERE name = ''' + @table_name + ''' AND schema_id = SCHEMA_ID(''silver''))
            DROP EXTERNAL TABLE silver.' + @table_name + ';';

    EXEC sp_executesql @drop_sql_stmt;
END;
GO

USE nyc_taxi_ldw;

IF NOT EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'nyc_taxi_src')
    CREATE EXTERNAL DATA SOURCE nyc_taxi_src
    WITH (
        LOCATION = 'https://projectnycsa.blob.core.windows.net/projectnycdl/'
    );
